def transform(grid):
    # Fill straight strips inward from each colored edge marker; preserve other cells.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # infer most common background
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    marks = [(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v != bg]
    # For a contiguous edge bar, extend each bar in its inward direction.
    # marker bars define color, sparse cells otherwise preserved.
    by_color = {}
    for r,c,v in marks: by_color.setdefault(v, []).append((r,c))
    # Detect identical-color runs on outer edges and fill toward opposite edge.
    for v, pts in by_color.items():
      if len(pts) > 1:
        rows = {r for r,c in pts}; cols = {c for r,c in pts}
        if len(rows)==1:
          r=next(iter(rows)); cs=sorted(cols)
          if cs[0]==0 or cs[-1]==w-1:
            direction = 1 if cs[0]==0 else -1
            for rr in range(h):
              for cc in cs: out[rr][cc]=v
        elif len(cols)==1:
          c=next(iter(cols)); rs=sorted(rows)
          if rs[0]==0 or rs[-1]==h-1:
            for rr in range(h): out[rr][c]=v
    return out
