def transform(grid):
    # Expand the two 2x2 corner bars inward, replacing the intervening background;
    # diagonal 2 markers encode the staircase boundary; use bar color as fill.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    bg=max(set(x for row in grid for x in row), key=lambda x:sum(r.count(x) for r in grid))
    bars=[]
    for r,row in enumerate(grid):
      cs=[c for c,v in enumerate(row) if v!=bg and v!=2]
      if len(cs)>=2: bars.append((r,cs[0],cs[-1],row[cs[0]]))
    # Project bottom-left bar to top following staircase markers (likely inward step-fill)
    # and top-right bar down its region.
    if len(bars)>=2:
      (r1,a,b,v1),(r2,c,d,v2)=bars[0],bars[-1]
      # bars occupy horizontal endpoints; extend each segment parallel to its rows
      for rr in range(h):
        if rr>=r1:
          for cc in range(a,b+1):
            if out[rr][cc]==bg: out[rr][cc]=v1
        if rr<=r2:
          for cc in range(c,d+1):
            if out[rr][cc]==bg: out[rr][cc]=v2
    # diagonal marker 2s delimit a staircase of 4s, with 7 fill on inside
    pts=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==2]
    for r,c in pts: out[r][c]=2
    return out
