    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Isolated markers are 4 and project their original color toward the nearest
    # long straight edge line, stopping at that line.
    lines=[]
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid))
    for r,row in enumerate(grid):
        cs=[c for c,v in enumerate(row) if v!=bg]
        if len(cs)>=2 and all(row[c]==row[cs[0]] for c in cs): lines.append(('h',r,min(cs),max(cs)))
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]!=bg]
        if len(rs)>=2 and all(grid[r][c]==grid[rs[0]][c] for r in rs): lines.append(('v',c,min(rs),max(rs)))
    linecells=set()
    for typ,k,a,b in lines:
        if typ=='h': linecells.update((k,c) for c in range(a,b+1))
        else: linecells.update((r,k) for r in range(a,b+1))
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==bg or (r,c) in linecells: continue
            out[r][c]=4
            # seek nearest same-row line to the right; otherwise same-column line below
            opts=[]
            for typ,k,a,b in lines:
                if typ=='h' and k==r and a>c: opts.append((a-c,'h',k,a,b))
                if typ=='v' and k==c and a>r: opts.append((a-r,'v',k,a,b))
            if opts:
                _,typ,k,a,b=min(opts)
                if typ=='h':
                    for cc in range(c+1,a): out[r][cc]=v
                else:
                    for rr in range(r+1,a): out[rr][c]=v
    return out
