    out = [row[:] for row in grid]
    # Isolated markers become 4; extend each marker's original color along its
    # column to the nearest horizontal edge bar spanning that column.
    bars = []
    for r in (0, h - 1):
        cols = [c for c, value in enumerate(grid[r]) if value != 8]
        if len(cols) >= 2:
            bars.append((r, min(cols), max(cols)))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (8, 3):
                continue
            out[r][c] = 4
            targets = [br for br, left, right in bars if left <= c <= right]
            if targets:
                target = min(targets, key=lambda br: abs(br-r))
                step = 1 if target > r else -1
                for rr in range(r+step, target, step):
                    if grid[rr][c] == 8:
                        out[rr][c] = color
    return out
