def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Each bar projects its innermost endpoint as a line perpendicular to itself.
    bars=[]
    for r in (0,h-1):
        cs=[c for c,v in enumerate(grid[r]) if v==3]
        if len(cs)>=2: bars.append((r,min(cs),max(cs)))
    # project from the right end of top bar and left end of bottom bar
    for r,a,b in bars:
        c=a if a>0 else b
        step=1 if r==0 else -1
        for rr in range(r+step, h if step>0 else -1, step):
            if grid[rr][c]==2:
                out[rr][c]=4; break
            if grid[rr][c]==8: out[rr][c]=2
    # isolated dots are recolored 4; their rays join the nearby projected line
    for r in range(h):
        for c in range(w):
            if grid[r][c]==2: out[r][c]=4
    return out
